static const u8 *const sCastPortraits[] = {gCastPortrait_Silas, gCastPortrait_Kade, gCastPortrait_Ashe, gCastPortrait_Nico, gCastPortrait_Riven, gCastPortrait_Emi, gCastPortrait_Vera, gCastPortrait_Lume, gCastPortrait_Mochi, gCastPortrait_Zuri};
