static const struct CastCharacter sCastCharacters[] = {
    {.graphics = OBJ_EVENT_GFX_CAST_SILAS,
     .trainer = CAST_TRAINER_SILAS,
     .requirement = CAST_REQ_SPECIES,
     .value = SPECIES_WURMPLE,
     .walkSlot = 1,
     .name = _("SILAS$"),
     .intro = _("SILAS: I am Silas. My field\nseminar has one attendee: a\lWURMPLE. It has eaten the\lattendance sheet. Could you show\lme one? Yours stays with you.$"),
     .request = _("SILAS: A WURMPLE from the nearby\ngrass will do. I need to observe\lit, not borrow it. My lecture\lhas already suffered enough.$"),
     .ready = _("SILAS: Excellent antennae.\nBetter attention span than my\lsupervisor. May I test a\lfour-Pokemon field team against\lyours?$"),
     .join = _("SILAS: I kept predicting your\nchoices instead of watching you.\lLesson received. Could I travel\lwith you? I can take notes and\loccasionally hints.$"),
     .lore = {_("SILAS: My mother repaired radios\nin OLDALE. I liked finding\lvoices inside things people\lthought were broken.$"), _("SILAS: My first experiment was\nteaching a MAGNEMITE to ring the\ldinner bell. It invited every\lspoon in town.$"), _("SILAS: I won a laboratory\nplacement. Then I stopped going\loutside. Every report was\lperfect. I was terribly lonely.$"), _("SILAS: My supervisor called\nfieldwork a distraction. I\lbelieved him until a patient\lRALTS refused to enter the lab.$"), _("SILAS: I came here to prove my\nresearch mattered. Now I think\lnoticing who needs help is\lresearch too.$"), _("SILAS: I wrote home about you.\nMother asked whether my new\lcolleague eats properly.\lCongratulations. You have passed\lpeer review.$")},
     .loreExpression = {1, 7, 4, 0, 1, 7}},
    {.graphics = OBJ_EVENT_GFX_CAST_KADE,
     .trainer = CAST_TRAINER_KADE,
     .requirement = CAST_REQ_SPECIES,
     .value = SPECIES_RATTATA,
     .walkSlot = 1,
     .name = _("KADE$"),
     .intro = _("KADE: Kade. Courier. A RATTATA\nkeeps stealing my delivery\lstraps. Show me one and I might\lfinally negotiate with\lmanagement. No, I am not keeping\lyours.$"),
     .request = _("KADE: RATTATA live on ROUTE 1.\nJust show me one in your party.\lI have prepared a stern but\lnutritionally fair speech.$"),
     .ready = _("KADE: Your RATTATA looks\ninnocent. Suspicious. Want a\lfour-Pokemon battle? I need\lsomeone who can keep moving when\la plan falls apart.$"),
     .join = _("KADE: You looked after your team\neven while winning. That\lmatters. Want company? I know\lroads, repairs, and when to stop\lasking questions.$"),
     .lore = {_("KADE: I used to deliver medicine\nwith my older sister. She knew\levery shortcut. I knew every\lbakery.$"), _("KADE: She made me practice\nsmiling at customers. A child\lasked why the parcel looked\lfrightened.$"), _("KADE: Once I was late with an\nimportant delivery. Nobody\lblamed me. I kept hearing blame\lanyway.$"), _("KADE: I started taking every job\nalone. It is hard to disappoint\la partner if you never let one\ljoin you.$"), _("KADE: A HOUNDOUR followed me\nthrough a storm. I told it to go\lhome. It sat on my boots until I\lasked for help.$"), _("KADE: Travelling with you feels\nless like making up for a\lmistake. More like going\lsomewhere. I could get used to\lthat.$")},
     .loreExpression = {0, 7, 4, 0, 1, 1}},
    {.graphics = OBJ_EVENT_GFX_CAST_ASHE,
     .trainer = CAST_TRAINER_ASHE,
     .requirement = CAST_REQ_STEPS,
     .value = 160,
     .walkSlot = 0,
     .name = _("ASHE$"),
     .intro = _("ASHE: I am Ashe. I am recording\na walking song. Could you take\l160 steps after this chat? I\lneed a rhythm that is not my own\lnervous pacing.$"),
     .request = _("ASHE: Still collecting the\nfootsteps. Keep walking; your\lnormal travels count. Please do\lnot buy a drum just for me.$"),
     .ready = _("ASHE: That rhythm works. Want to\ntry a four-Pokemon battle? My\lband practices being loud\lwithout being cruel.$"),
     .join = _("ASHE: You gave everyone room to\nmove. I like that. Could I come\lalong? I am better at listening\lthan introductions.$"),
     .lore = {_("ASHE: I played in my uncle's\ncafe. Mostly when the washing\lmachine was loud enough to cover\lmy mistakes.$"), _("ASHE: WHISMUR was my first\naudience. It applauded by\lknocking every cup off a shelf.\lMixed reviews.$"), _("ASHE: I froze at a festival\naudition. I still remember the\lsilence more clearly than any\lsong I have written.$"), _("ASHE: My uncle kept my name on\nthe cafe noticeboard. No\ldeadline. Just a place to return\lwhen I was ready.$"), _("ASHE: I thought confidence had\nto arrive before the music. You\lkeep doing brave things while\ladmitting you are nervous.$"), _("ASHE: I am writing a song I\nmight actually play for people.\lThere is a part for footsteps.\lYours, if that is all right.$")},
     .loreExpression = {0, 7, 4, 1, 0, 1}},
    {.graphics = OBJ_EVENT_GFX_CAST_NICO,
     .trainer = CAST_TRAINER_NICO,
     .requirement = CAST_REQ_ITEM,
     .value = ITEM_ORAN_BERRY,
     .walkSlot = 1,
     .name = _("NICO$"),
     .intro = _("NICO: Nico! Baker, traveller,\noccasional smoke alarm. Bring me\lone ORAN BERRY and I will\ldemonstrate a recipe with an\lactual success rate.$"),
     .request = _("NICO: One ORAN BERRY. The nearby\nberry trees can help. The recipe\lspecifically says not to\lsubstitute a blue rock.$"),
     .ready = _("NICO: Trade me one ORAN BERRY\nand a four-Pokemon battle? The\lberry goes into trail bread. The\lbattle settles who gets the\lheroic slice.$"),
     .join = _("NICO: Your team shares the work.\nI like your kitchen.\lMetaphorical kitchen. Want me to\lcome along? I pack food and\lterrible timing.$"),
     .lore = {_("NICO: My grandmother taught me\nto bake by feel. She meant the\ldough. I thought she meant\ldramatic instinct.$"), _("NICO: Her shop had a spare chair\nfor anyone who needed somewhere\lwarm. Sometimes the chair made\lmore money than the bread.$"), _("NICO: When she closed the shop,\nI rushed into opening my own. I\lwanted to keep everything\lexactly the same.$"), _("NICO: I burned through my\nsavings trying to copy her life.\lShe told me a recipe is a\lbeginning, not an obligation.$"), _("NICO: Now I collect meals and\nthe stories attached to them.\lTravelling with you has improved\lboth the menu and the stories.$"), _("NICO: When I open a place again,\nthere will be a spare chair. And\la smoke alarm with union\lrepresentation.$")},
     .loreExpression = {7, 1, 4, 0, 1, 7}},
    {.graphics = OBJ_EVENT_GFX_CAST_RIVEN,
     .trainer = CAST_TRAINER_RIVEN,
     .requirement = CAST_REQ_SPECIES,
     .value = SPECIES_ABRA,
     .walkSlot = 1,
     .name = _("RIVEN$"),
     .intro = _("RIVEN: Riven, at your service! I\nseek an ABRA for a study of\ldisappearing before\lintroductions. Show me one. It\lremains your mysterious\lassociate.$"),
     .request = _("RIVEN: ABRA can be found north\nof CERULEAN. I only need to see\lyours. Apparently shouting STAY\lis not a successful research\lmethod.$"),
     .ready = _("RIVEN: A splendid assistant,\nentirely yours. Care for a\lfour-Pokemon exhibition battle?\lNothing up my sleeve except a\lconcerning amount of lint.$"),
     .join = _("RIVEN: You saw through the trick\nand still treated the performers\lkindly. May I join you? I\lpromise to announce any dramatic\lentrances in advance.$"),
     .lore = {_("RIVEN: My father performed\nlittle card tricks at the docks.\lHe could make an exhausting day\lfeel briefly impossible.$"), _("RIVEN: He taught me the grand\ngesture first. I spent a week\lbowing before I was allowed to\ltouch a card.$"), _("RIVEN: I once used a trick to\nhide a mistake from a friend. It\lworked beautifully. That was the\lworst part.$"), _("RIVEN: She found out. We are\ntalking again, slowly. Being\lforgiven is not the same thing\las skipping the work.$"), _("RIVEN: Now I tell an audience\nwhen a trick begins. Wonder is\lnicer when everyone has agreed\lto be fooled.$"), _("RIVEN: You never ask me to be\nimpressive all the time. It is\lan unusual luxury. I am\lconsidering a less dramatic\lthank-you.$")},
     .loreExpression = {6, 7, 4, 0, 1, 1}},
    {.graphics = OBJ_EVENT_GFX_CAST_EMI,
     .trainer = CAST_TRAINER_EMI,
     .requirement = CAST_REQ_STEPS,
     .value = 64,
     .walkSlot = 1,
     .name = _("EMI$"),
     .intro = _("EMI: Emi. I am trying to write\nabout a journey without leaving\lthis sign. Walk 64 steps after\lwe talk? I need evidence that\lbeginnings survive movement.$"),
     .request = _("EMI: Take a little walk. Your\nordinary steps count. I tried\loutsourcing this to MURKROW. It\lsubmitted a twig.$"),
     .ready = _("EMI: You returned. The poem now\nhas a second line. Want a\lfour-Pokemon battle? My team\linsists I experience a plot.$"),
     .join = _("EMI: You were kind to your team\nwhen things got messy. I would\llike to see where you go next.\lWant me to travel with you?$"),
     .lore = {_("EMI: I grew up above my aunt's\nbookshop. Every customer thought\la quiet child was a spare\lbookmark.$"), _("EMI: I wrote my first poem about\nthe moon. It was actually a\lstreetlamp. Strong opening. Weak\lastronomy.$"), _("EMI: I stopped showing people my\nwork after someone laughed at a\lserious poem. I decided every\lpoem had to be a joke first.$"), _("EMI: My aunt kept the original\nin her till. She said a clumsy\lhonest thing can still be worth\lkeeping.$"), _("EMI: Sometimes I make a joke\nbefore saying I care. You are\lgetting very inconveniently good\lat hearing the second part.$"), _("EMI: I sent her a new poem. No\ndisguise, no punchline. I would\llike to read it to you one day.\lWhen my knees stop writing their\lown review.$")},
     .loreExpression = {0, 7, 4, 0, 1, 1}},
    {.graphics = OBJ_EVENT_GFX_CAST_VERA,
     .trainer = CAST_TRAINER_VERA,
     .requirement = CAST_REQ_ITEM,
     .value = ITEM_PARALYZE_HEAL,
     .walkSlot = 1,
     .name = _("VERA$"),
     .intro = _("VERA: Vera! I repair things.\nSometimes the thing is my\lconfidence after a repair. Bring\lone PARALYZE HEAL for the\lworkshop first-aid kit?$"),
     .request = _("VERA: The MART sells PARALYZE\nHEAL. One is enough. Safety\lequipment comes before the\limpressive sparks. I am\llearning.$"),
     .ready = _("VERA: Donate one PARALYZE HEAL\nto the kit and try a\lfour-Pokemon test battle? No\lprototypes attached to you, I\lpromise.$"),
     .join = _("VERA: You adapted instead of\nblaming your team. That is good\lengineering. Want a mechanic\lalong? I can promise effort and\llabel the experimental bits.$"),
     .lore = {_("VERA: My father fixed fishing\nreels. I improved one until it\lcould retrieve a hat from three\lstreets away.$"), _("VERA: He never said I was too\nmuch. He asked what problem I\lactually wanted to solve.\lInfuriatingly useful question.$"), _("VERA: I built a motor too\nquickly and frightened my\lELECTRIKE. Nothing broke. Its\ltrust still needed repairing.$"), _("VERA: Now I ask before trying\nnew equipment around Pokemon.\lBeing clever does not make\lsomeone else a test bench.$"), _("VERA: I want to make travelling\neasier for people whose bodies\lneed different routes. That is a\lproblem worth taking slowly.$"), _("VERA: I have drawn a folding\nrest seat. You are listed as a\lconsultant. Payment is one\lextremely official sit-down.$")},
     .loreExpression = {7, 1, 4, 0, 1, 7}},
    {.graphics = OBJ_EVENT_GFX_CAST_LUME,
     .trainer = CAST_TRAINER_LUME,
     .requirement = CAST_REQ_SPECIES,
     .value = SPECIES_NINCADA,
     .walkSlot = 1,
     .name = _("LUME$"),
     .intro = _("LUME: Lume. I collect local\nstories. A farmer says NINCADA\lcan hear roots gossip. Show me\lone from ROUTE 116? We can ask\lpolitely. It stays yours.$"),
     .request = _("LUME: A NINCADA from ROUTE 116,\nin your party. I am recording a\lstory, not asking you to prove a\lghost exists.$"),
     .ready = _("LUME: It is listening. Possibly\nto roots. Possibly to lunch.\lShall we have a four-Pokemon\lbattle before writing the\lconclusion?$"),
     .join = _("LUME: You let a strange story be\nstrange without laughing at its\lteller. I appreciate that. Could\lI join your travels?$"),
     .lore = {_("LUME: My grandmother told\nstories to keep children close\lon foggy roads. I used to think\lshe knew every ghost personally.$"), _("LUME: She admitted one haunted\ngate was just a badly oiled\lhinge. She still charged it rent\lin her stories.$"), _("LUME: After she died, I tried to\nwrite down every word. I was\lfrightened that forgetting a\lsentence meant losing her again.$"), _("LUME: A neighbour remembered a\ndifferent ending. It was hers\ltoo. People leave pieces of\lthemselves with more than one\lperson.$"), _("LUME: I ask who a story helps,\nand who it leaves out. An old\lstory can deserve affection and\lstill need a better ending.$"), _("LUME: I am writing one about\nthese travels. You do not have\lto do anything legendary.\lSomeone remembering you kindly\lis enough.$")},
     .loreExpression = {0, 7, 4, 1, 0, 1}},
    {.graphics = OBJ_EVENT_GFX_CAST_MOCHI,
     .trainer = CAST_TRAINER_MOCHI,
     .requirement = CAST_REQ_ITEM,
     .value = ITEM_POKE_BALL,
     .walkSlot = 1,
     .name = _("MOCHI$"),
     .intro = _("MOCHI: Mochi! I am making a\ntravelling outfit with real\lpockets. Could you spare one\lPOKE BALL for a clasp test?\lUnused, please. No surprise\ltenants.$"),
     .request = _("MOCHI: Just one ordinary POKE\nBALL from the MART. I am testing\lthe fastening, not borrowing\lanyone inside it.$"),
     .ready = _("MOCHI: Let me use one POKE BALL\nfor the test, then a\lfour-Pokemon battle? Clothing\lshould survive actual movement.\lSo should my sales pitch.$"),
     .join = _("MOCHI: You noticed effort\ninstead of appearances.\lExcellent taste. Want company? I\lcan mend sleeves and offer\lopinions with a reasonable\lreturn policy.$"),
     .lore = {_("MOCHI: My first designs were for\na shy friend who hated being\lphotographed. I learned to ask\lhow clothes felt before asking\lhow they looked.$"), _("MOCHI: My first bag had\ndecorative pockets. My friend\lreturned it with a drawing of an\langry sandwich.$"), _("MOCHI: I once changed my style\nto fit a fashion contest. I\lplaced well and could not\lrecognise a single thing I had\lmade.$"), _("MOCHI: My friend asked when I\nwould make something with an\lactual place for her lunch. That\lwas a very good review.$"), _("MOCHI: I want people to feel\nlike themselves, with room to\lmove. Beautiful is allowed to be\lcomfortable.$"), _("MOCHI: I have a sketch of our\ntravelling clothes. Every pocket\lworks. The angry sandwich has\lfinally approved the collection.$")},
     .loreExpression = {1, 7, 4, 0, 1, 7}},
    {.graphics = OBJ_EVENT_GFX_CAST_ZURI,
     .trainer = CAST_TRAINER_ZURI,
     .requirement = CAST_REQ_ITEM,
     .value = ITEM_POTION,
     .walkSlot = 1,
     .name = _("ZURI$"),
     .intro = _("ZURI: Zuri! I am planning a\ncommunity mural. Before the\lpaint, a first-aid kit. Could\lyou bring one POTION? My crew\lincludes very ambitious elbows.$"),
     .request = _("ZURI: One POTION for the crew.\nThe MART has them. I want us\lprepared, not auditioning for an\laccident.$"),
     .ready = _("ZURI: Donate one POTION and try\na four-Pokemon battle? I need a\lpartner who can improvise\lwithout treating everyone else\las scenery.$"),
     .join = _("ZURI: You gave your team space\nto shine. Want me along? I\lcollect colours, stories, and\loccasionally permission forms.$"),
     .lore = {_("ZURI: I painted with my brother\nbehind our old home. He made\lenormous skies. I filled them\lwith birds that looked like bent\lspoons.$"), _("ZURI: He called it my signature\nbird. I sold one sketch before\llearning which end of a wing was\lwhich.$"), _("ZURI: When the building was\nsold, our wall was painted over.\lI was angrier about that than I\lknew how to explain.$"), _("ZURI: I started asking people\nwhat they wanted remembered\lbefore planning a mural. A wall\lbelongs to more than the person\lholding a brush.$"), _("ZURI: I still miss that sky. But\nthe neighbours remember it. I am\llearning that paint is one way\lto keep something, not the only\lway.$"), _("ZURI: There is a new mural in my\nsketchbook. Everyone we have\lhelped gets a little space. Yes,\lthe bent-spoon birds are\lstaying.$")},
     .loreExpression = {1, 7, 4, 0, 1, 7}},
};
